(async()=>{const host=document.querySelector('#homeBooks');if(!host)return;try{const d=await LibraryData.json('books-data.json'),ids=['w5cf4c1311fe6','wc03976e8c09d','waf31e9ccbb25'];for(const id of ids){const b=d.books.find(b=>b.id===id);if(!b)continue;const l=document.createElement('a');l.className='book-tile';l.href='book.html?id='+b.id;if(b.image){const image=document.createElement('img');image.src=b.image;image.alt='Reference-copy title page: '+b.title;image.loading='lazy';l.append(image)}const h=document.createElement('h3');h.textContent=b.title;const p=document.createElement('p');p.textContent=b.authorNames.join(' · ');const date=document.createElement('p');date.textContent=b.year+' · Reference-copy gallery';l.append(h,p,date);if(window.LibraryConfidence)l.append(LibraryConfidence.badge(b.confidence||'low','Record'));host.append(l)}}catch{host.textContent='Open the book catalogue to explore the records.'}})();
